"""Shared helpers for the Bedrock labs.

Why this file exists: model IDs change often, so labs read BEDROCK_MODEL_ID from the environment
instead of hard-coding one. Discover valid IDs for YOUR Region with discover_models.py.
"""
import os

import boto3
from botocore.config import Config

REGION = os.environ.get("AWS_REGION", "us-east-1")


def model_id() -> str:
    mid = os.environ.get("BEDROCK_MODEL_ID")
    if not mid:
        raise SystemExit(
            "Set BEDROCK_MODEL_ID first. Find one with:  python discover_models.py\n"
            "PowerShell:  $env:BEDROCK_MODEL_ID = '<model id or inference profile id>'"
        )
    return mid


def runtime_client(max_attempts: int = 3, read_timeout: int = 120):
    """bedrock-runtime = inference calls. (Plain 'bedrock' = control plane: list/manage things.)"""
    return boto3.client(
        "bedrock-runtime",
        region_name=REGION,
        config=Config(
            retries={"max_attempts": max_attempts, "mode": "adaptive"},  # SDK backoff + client-side rate limiting
            read_timeout=read_timeout,  # LLM answers can take a while; the default is 60 s
            connect_timeout=10,
        ),
    )


def control_client():
    return boto3.client("bedrock", region_name=REGION)

"""Lab 01-1d: A production-style Converse wrapper: retry with exponential backoff + jitter,
no retry for caller mistakes, and a fallback model.

Run:  python converse_resilient.py "Summarise what a vector store is."
Env : BEDROCK_MODEL_ID (required), BEDROCK_FALLBACK_MODEL_ID (optional), AWS_REGION
Test: python test_converse_resilient_offline.py   (no AWS needed)
"""
import os
import random
import sys
import time
from typing import Callable

from botocore.exceptions import ClientError, ConnectTimeoutError, ReadTimeoutError

# Transient problems: another attempt can succeed. Names appear both as API exception types and as
# documented error labels, so both spellings are listed. (Verified labels: ThrottlingException 429,
# ServiceUnavailable 503, InternalFailure 500, overloaded_error 529.)
RETRYABLE = {
    "ThrottlingException", "TooManyRequestsException",
    "ServiceUnavailable", "ServiceUnavailableException",
    "InternalFailure", "InternalServerException",
    "overloaded_error", "ModelTimeoutException", "ModelNotReadyException",
}
# Caller mistakes: retrying cannot help and only wastes time and money.
NOT_RETRYABLE = {
    "ValidationException", "ValidationError", "AccessDeniedException", "ResourceNotFoundException",
    "ResourceNotFound", "FTUFormNotFilled", "RequestExpired", "InvalidClientTokenId",
}


def backoff_delay(attempt: int, base: float = 0.5, cap: float = 20.0) -> float:
    """'Full jitter': random between 0 and min(cap, base * 2**attempt). Spreads out synchronized retries."""
    return random.uniform(0, min(cap, base * (2 ** attempt)))


def call_with_retry(call: Callable[[], dict], max_attempts: int = 5,
                    sleep: Callable[[float], None] = time.sleep) -> dict:
    last_exc: Exception | None = None
    for attempt in range(max_attempts):
        try:
            return call()
        except ClientError as exc:
            code = exc.response["Error"]["Code"]
            if code in NOT_RETRYABLE or code not in RETRYABLE:
                raise  # unknown codes are not retried blindly
            last_exc = exc
        except (ReadTimeoutError, ConnectTimeoutError) as exc:
            last_exc = exc  # network timeouts are retryable
        if attempt < max_attempts - 1:
            sleep(backoff_delay(attempt))
    assert last_exc is not None
    raise last_exc


def converse_with_fallback(client, primary_model: str, fallback_model: str | None, **request) -> dict:
    """Try the primary model with retries; if it still fails with a transient error, try the fallback."""
    try:
        return call_with_retry(lambda: client.converse(modelId=primary_model, **request))
    except Exception as exc:
        code = exc.response["Error"]["Code"] if isinstance(exc, ClientError) else type(exc).__name__
        if fallback_model and (code in RETRYABLE or not isinstance(exc, ClientError)):
            print(f"[fallback] primary failed ({code}); trying fallback model")
            return call_with_retry(lambda: client.converse(modelId=fallback_model, **request))
        raise


def main(prompt: str) -> None:
    from _common import model_id, runtime_client  # imported here so the offline test needs no AWS setup

    client = runtime_client(max_attempts=1)  # SDK retries OFF here: our wrapper owns the retry policy
    resp = converse_with_fallback(
        client, model_id(), os.environ.get("BEDROCK_FALLBACK_MODEL_ID"),
        messages=[{"role": "user", "content": [{"text": prompt}]}],
        inferenceConfig={"maxTokens": 300, "temperature": 0.2},
    )
    print("".join(b["text"] for b in resp["output"]["message"]["content"] if "text" in b))
    print("\nusage:", resp["usage"], "| stopReason:", resp["stopReason"])


if __name__ == "__main__":
    main(" ".join(sys.argv[1:]) or "Summarise what a vector store is.")
